"""DMGHG Local Bridge Service (动漫共和国本地原生桥接服务)

Provides headless HTTP bridge to installed DMGHG Windows native libraries.
"""
import argparse
import ctypes
import http.server
import json
import os
from pathlib import Path
import socket
import socketserver
import sys
import tempfile
import threading
from urllib.parse import parse_qs, urlsplit


class Bridge:
    READ_COMMANDS = {
        "app.ping", "catalog.get_channels", "catalog.get_banners",
        "catalog.get_video_list", "catalog.search_video", "catalog.get_video_key",
        "catalog.get_video_detail", "catalog.get_channel_detail", "video.play",
    }

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("DMGHG bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError("electron_bridge.dll missing from app dir")
        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-bridge-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"
        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]
        self.lock = threading.RLock()
        self.version = self._read_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("Native bridge failed to initialize")

    def _read_version(self, exe):
        version = ctypes.windll.version
        size = version.GetFileVersionInfoSizeW(str(exe), None)
        if not size:
            raise RuntimeError("Cannot read application version")
        buffer = ctypes.create_string_buffer(size)
        if not version.GetFileVersionInfoW(str(exe), 0, size, buffer):
            raise RuntimeError("Cannot read version info")
        info = ctypes.c_void_p()
        length = ctypes.c_uint()
        if not version.VerQueryValueW(buffer, "\\", ctypes.byref(info), ctypes.byref(length)):
            raise RuntimeError("Version structure missing")
        fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
        if fields[0] != 0xFEEF04BD or length.value < 52:
            raise RuntimeError("Invalid version structure")
        return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"

    def call(self, command, payload=None):
        if command not in self.READ_COMMANDS:
            raise ValueError(f"Command '{command}' is not in the read-only whitelist")
        request = {
            "request_id": "headless-bridge-call",
            "protocol_version": 1,
            "command": command,
            "payload": payload or {}
        }
        with self.lock:
            previous = Path.cwd()
            try:
                os.chdir(self.app_dir)
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8")
                )
                if not ptr:
                    raise RuntimeError("Bridge returned null")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(previous)
        if response.get("ok") is not True:
            err = response.get("error", {})
            raise RuntimeError(f"{err.get('code')}: {err.get('message')}")
        return response.get("data")

    def close(self):
        if self.handle:
            self.dll.dmghg_service_free(self.handle)
            self.handle = None


class ThreadingServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def get_request(self):
        sock, addr = super().get_request()
        # Enforce server-side 5s timeout on client sockets to prevent slow client hangs
        sock.settimeout(5.0)
        return sock, addr


def make_handler(bridge):
    class BridgeHandler(http.server.BaseHTTPRequestHandler):
        timeout = 5.0

        def log_message(self, format, *args):
            pass

        def send_json(self, status, data):
            payload = json.dumps(data, ensure_ascii=False).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(payload)))
            self.send_header("Connection", "close")
            self.end_headers()
            self.wfile.write(payload)

        def do_GET(self):
            parsed = urlsplit(self.path)
            path = parsed.path
            qs = parse_qs(parsed.query)

            if path == "/ping":
                try:
                    res = bridge.call("app.ping")
                    return self.send_json(200, {"ok": True, "ping": res})
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            elif path == "/channels":
                try:
                    channels = bridge.call("catalog.get_channels")
                    return self.send_json(200, channels)
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            elif path == "/api/list":
                channel = qs.get("channel", [None])[0]
                page = int(qs.get("page", ["1"])[0])
                payload = {"page": page}
                if channel:
                    try:
                        payload["channel"] = int(channel)
                    except ValueError:
                        payload["channel"] = channel
                try:
                    data = bridge.call("catalog.get_video_list", payload)
                    return self.send_json(200, data)
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            elif path == "/api/search":
                key = qs.get("key", [""])[0]
                page = qs.get("page", ["1"])[0]
                try:
                    data = bridge.call("catalog.search_video", {"key": key, "page": str(page)})
                    return self.send_json(200, data)
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            elif path == "/api/detail":
                vid = qs.get("id", [""])[0]
                try:
                    data = bridge.call("catalog.get_video_detail", {"id": str(vid)})
                    return self.send_json(200, data)
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            elif path == "/api/play":
                vid = qs.get("id", [""])[0]
                part = qs.get("part", [""])[0]
                play_tag = qs.get("play", ["cn"])[0]
                try:
                    data = bridge.call("video.play", {
                        "id": str(vid),
                        "part": part,
                        "play": play_tag,
                        "resolve": True
                    })
                    item = data["list"][data.get("default", 0)]
                    return self.send_json(200, {"url": item["url"], "headers": item.get("headers") or {}})
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            else:
                return self.send_json(404, {"ok": False, "error": "Not Found"})

        def do_POST(self):
            parsed = urlsplit(self.path)
            path = parsed.path

            content_len = self.headers.get("Content-Length")
            if not content_len:
                return self.send_json(400, {"ok": False, "error": "Missing Content-Length"})
            try:
                length = int(content_len)
                if length > 1048576:
                    return self.send_json(413, {"ok": False, "error": "Payload too large"})
                body_bytes = self.rfile.read(length)
                req_data = json.loads(body_bytes.decode("utf-8"))
            except (ValueError, UnicodeDecodeError, socket.timeout) as e:
                return self.send_json(400, {"ok": False, "error": f"Invalid JSON or timeout: {e}"})

            if path == "/call":
                command = req_data.get("command")
                payload = req_data.get("payload", {})
                if not command or command not in bridge.READ_COMMANDS:
                    return self.send_json(400, {"ok": False, "error": f"Forbidden or unknown command: {command}"})
                try:
                    res = bridge.call(command, payload)
                    return self.send_json(200, res)
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            elif path == "/api/play":
                vid = req_data.get("id")
                part = req_data.get("part")
                play_tag = req_data.get("play", "cn")
                try:
                    data = bridge.call("video.play", {
                        "id": str(vid),
                        "part": str(part),
                        "play": play_tag,
                        "resolve": True
                    })
                    item = data["list"][data.get("default", 0)]
                    return self.send_json(200, {"url": item["url"], "headers": item.get("headers") or {}})
                except Exception as e:
                    return self.send_json(500, {"ok": False, "error": str(e)})

            else:
                return self.send_json(404, {"ok": False, "error": "Not Found"})

    return BridgeHandler


def main():
    parser = argparse.ArgumentParser(description="DMGHG Local Bridge Service")
    parser.add_argument("--app-dir", required=True, help="DMGHG installed directory")
    parser.add_argument("--port", type=int, default=18002, help="Loopback port (18000, 18001, 18002)")
    args = parser.parse_args()

    app_dir = Path(args.app_dir).resolve()
    if not app_dir.is_dir():
        sys.stderr.write(f"App directory not found: {app_dir}\n")
        sys.exit(1)

    try:
        bridge = Bridge(app_dir)
    except Exception as e:
        sys.stderr.write(f"Bridge init error: {e}\n")
        sys.exit(1)

    handler_cls = make_handler(bridge)
    server = ThreadingServer(("127.0.0.1", args.port), handler_cls)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        bridge.close()


if __name__ == "__main__":
    main()

